    private static float[] Run(OptimizerBase optimizer, Reference r, IDictionary<string, double> options)
    {
        var p = new Tensor<float>((float[])r.P0.Clone(), r.Shape);
        optimizer.AddParamGroup(options).AddParameter(p);
        foreach (var g in r.Grads)
            optimizer.Step(new Dictionary<Tensor<float>, Tensor<float>> { [p] = new Tensor<float>((float[])g.Clone(), r.Shape) });
        return p.ToArray();
    }

    private static void AssertClose(float[] expected, float[] actual, double tolerance)
    {
        Assert.Equal(expected.Length, actual.Length);
        for (int i = 0; i < expected.Length; i++)
            Assert.True(Math.Abs(expected[i] - actual[i]) <= tolerance, $"element {i}: torch {expected[i]}, ours {actual[i]}");
    }

    [Theory]
    [InlineData("adafactor_matrix", 1e-2, 0.0)]
    [InlineData("adafactor_vector", 1e-2, 0.0)]
    [InlineData("adafactor_wd", 5e-2, 0.1)]
    public void Adafactor_MatchesTorch(string name, double lr, double weightDecay)
    {
        var r = Torch[name];
        var ours = Run(new AdafactorOptimizer(), r, new Dictionary<string, double> { ["lr"] = lr, ["weight_decay"] = weightDecay });
        AssertClose(r.P, ours, 1e-5);
    }

    [Theory]
    [InlineData("muon_tall", 0.0, 1.0)]
    [InlineData("muon_wide_moonshot", 1.0, 0.0)]
    public void Muon_MatchesTorchWithAFloat32Iteration(string name, double adjust, double nesterov)
    {
        var options = new Dictionary<string, double> { ["lr"] = 2e-2, ["adjust_lr_fn"] = adjust, ["nesterov"] = nesterov };
        AssertClose(Torch[name + "_f32"].P, Run(new MuonOptimizer(), Torch[name + "_f32"], options), 1e-5);
        // Stock torch orthogonalizes in bfloat16: same trajectory to bfloat16 accuracy.
        AssertClose(Torch[name].P, Run(new MuonOptimizer(), Torch[name], options), 2e-3);
    }

    [Fact]
    public void Muon_RejectsANonMatrixParameter()
    {
        var p = new Tensor<float>(new float[] { 1, 2, 3 }, new[] { 3 });
        var muon = new MuonOptimizer();
        muon.AddParamGroup().AddParameter(p);
        Assert.Throws<InvalidOperationException>(() =>
            muon.Step(new Dictionary<Tensor<float>, Tensor<float>> { [p] = new Tensor<float>(new float[] { 1, 1, 1 }, new[] { 3 }) }));
    }
}
